//! CC 5.3.3.10 link handshake (`CTKX` v2) known answers (CIRISEdge#1007).
//!
//! `vectors/transit/transit_ctkx_v2_v1.json` was generated by
//! `vectors/transit/gen.py`, written from `docs/TRANSIT_HANDSHAKE_V2.md`
//! independently of `ciris_crypto::transit`, over its own X-Wing (kyber-py's
//! FIPS 203 internals, pyca X25519, hashlib SHA3), self-checked against the
//! draft-11 known answers first. Every handshake, promotion and framing case
//! must come out byte for byte, and every refusal with its stated error.
#![cfg(feature = "transit")]

use ciris_crypto::transit::{
    encode_parts, Confirmation, Initiator, InitiatorLink, Mode, NoDecap, Reassembler, Responder,
    ResponderState, SharedSecret, TransitError,
};
use ciris_crypto::xwing::{XWingPublicKey, XWingSecretKey, XWING_CIPHERTEXT_LEN};
use ciris_crypto::CryptoError;
use serde_json::Value;

const VECTORS: &str = include_str!("vectors/transit/transit_ctkx_v2_v1.json");

fn doc() -> Value {
    serde_json::from_str(VECTORS).expect("vector file is JSON")
}

fn h(v: &Value) -> Vec<u8> {
    hex::decode(v.as_str().expect("hex string")).expect("hex")
}

fn arr<const N: usize>(v: &Value) -> [u8; N] {
    h(v).try_into().expect("length")
}

fn decap(
    sk: &XWingSecretKey,
) -> impl FnOnce(&[u8; XWING_CIPHERTEXT_LEN]) -> Result<SharedSecret, CryptoError> + '_ {
    move |ct| sk.decapsulate(ct)
}

/// One handshake's inputs, reconstructed from a vector case.
struct Case {
    link_id: [u8; 16],
    iid: String,
    rid: String,
    sr: XWingSecretKey,
    si: Option<XWingSecretKey>,
    bound_held: bool,
    e_seed: [u8; 32],
    r1: [u8; 64],
    r2: [u8; 64],
    r3: [u8; 64],
}

impl Case {
    fn from(c: &Value) -> Self {
        let i = &c["inputs"];
        Self {
            link_id: arr(&i["link_id"]),
            iid: i["initiator_key_id"].as_str().unwrap().to_owned(),
            rid: i["responder_key_id"].as_str().unwrap().to_owned(),
            sr: XWingSecretKey::from_seed(arr(&i["responder_static_seed"])),
            si: (!i["initiator_static_seed"].is_null())
                .then(|| XWingSecretKey::from_seed(arr(&i["initiator_static_seed"]))),
            bound_held: i["responder_holds_initiator_binding"].as_bool().unwrap(),
            e_seed: arr(&i["initiator_ephemeral_seed"]),
            r1: arr(&i["ct1_encaps_rand"]),
            r2: arr(&i["ct2_encaps_rand"]),
            r3: arr(&i["ct3_encaps_rand"]),
        }
    }

    fn pk_si(&self) -> Option<XWingPublicKey> {
        self.si.as_ref().map(XWingSecretKey::public_key)
    }

    fn start(&self) -> (ciris_crypto::transit::InitiatorState, Vec<u8>) {
        let pk_si = self.pk_si();
        Initiator::start(
            &self.link_id,
            &self.sr.public_key(),
            &self.rid,
            &self.iid,
            pk_si.as_ref(),
            &self.e_seed,
            &self.r1,
        )
        .unwrap()
    }

    fn accept(
        &self,
        msg1: &[u8],
        rid_expected: &str,
    ) -> Result<(ResponderState, Vec<u8>, Mode), TransitError> {
        let held = self.bound_held.then(|| self.pk_si()).flatten();
        let iid = self.iid.clone();
        Responder::accept(
            &self.link_id,
            &self.sr.public_key(),
            rid_expected,
            msg1,
            decap(&self.sr),
            move |kid, _| {
                assert_eq!(kid, iid);
                held
            },
            &self.r2,
            &self.r3,
        )
    }

    fn finish(&self, msg2: &[u8]) -> Result<InitiatorLink, TransitError> {
        let (st, _) = self.start();
        match &self.si {
            Some(si) => st.finish(msg2, Some(decap(si))),
            None => st.finish(msg2, None::<NoDecap>),
        }
    }

    /// The full handshake; returns both ends after a verified `CTKC`.
    fn run(&self) -> (InitiatorLink, ResponderState, Vec<u8>, Vec<u8>) {
        let (_, msg1) = self.start();
        let (mut rs, msg2, _) = self.accept(&msg1, &self.rid).unwrap();
        let il = self.finish(&msg2).unwrap();
        rs.confirm(il.ctkc()).unwrap();
        (il, rs, msg1, msg2)
    }
}

fn base<'a>(d: &'a Value, name: &str) -> &'a Value {
    d["handshakes"]
        .as_array()
        .unwrap()
        .iter()
        .find(|c| c["name"] == name)
        .unwrap_or_else(|| panic!("no base case {name}"))
}

#[test]
fn self_check_recorded() {
    let d = doc();
    assert_eq!(d["suite"], "transit_xwing_hkdf_sha256");
    assert_eq!(d["self_check"]["xwing_draft_11_cases"], 3);
}

#[test]
fn handshakes_byte_for_byte() {
    let d = doc();
    let cases = d["handshakes"].as_array().unwrap();
    assert_eq!(cases.len(), 3);
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let k = Case::from(c);
        assert_eq!(
            k.sr.public_key().as_bytes().to_vec(),
            h(&c["responder_static_pk"]),
            "{name}"
        );
        assert_eq!(
            XWingSecretKey::from_seed(k.e_seed)
                .public_key()
                .as_bytes()
                .to_vec(),
            h(&c["initiator_ephemeral_pk"]),
            "{name}"
        );
        let (st, msg1) = k.start();
        assert_eq!(msg1, h(&c["msg1"]), "{name}: msg1");
        let (mut rs, msg2, mode) = k.accept(&msg1, &k.rid).unwrap();
        assert_eq!(msg2, h(&c["msg2"]), "{name}: msg2");
        let want_mode = if c["mode"] == "mutual" {
            Mode::Mutual
        } else {
            Mode::FirstContact
        };
        assert_eq!(mode, want_mode, "{name}: mode");
        let il = match &k.si {
            Some(si) => st.finish(&msg2, Some(decap(si))),
            None => st.finish(&msg2, None::<NoDecap>),
        }
        .unwrap();
        assert_eq!(il.ctkc().to_vec(), h(&c["ctkc"]), "{name}: ctkc");
        assert_eq!(
            il.transcript_hash().to_vec(),
            h(&c["intermediate"]["h3"]),
            "{name}: h3"
        );
        for (side, keys, conf) in [
            ("initiator", il.keys(), il.confirm_key()),
            ("responder", rs.keys(), rs.confirm_key()),
        ] {
            assert_eq!(
                keys.k_i2r().to_vec(),
                h(&c["k_i2r"]),
                "{name} {side}: k_i2r"
            );
            assert_eq!(
                keys.k_r2i().to_vec(),
                h(&c["k_r2i"]),
                "{name} {side}: k_r2i"
            );
            assert_eq!(
                conf.as_bytes().to_vec(),
                h(&c["k_conf"]),
                "{name} {side}: k_conf"
            );
        }
        assert_eq!(
            ciris_crypto::transit::bound(&k.iid, &k.rid).unwrap(),
            h(&c["intermediate"]["bound"]),
            "{name}: bound"
        );
        let want = if c["confirm_outcome"] == "attributed" {
            Confirmation::Attributed
        } else {
            Confirmation::FirstContactConfirmed
        };
        assert_eq!(rs.confirm(il.ctkc()).unwrap(), want, "{name}: confirm");
        assert_eq!(
            rs.is_attributed(),
            want == Confirmation::Attributed,
            "{name}"
        );
    }
}

#[test]
fn promotion_byte_for_byte() {
    let d = doc();
    let p = &d["promotions"][0];
    let k = Case::from(base(&d, p["base"].as_str().unwrap()));
    let (mut il, mut rs, _, _) = k.run();
    let pk_si = k.pk_si().unwrap();
    let msg3 = rs
        .promote(&pk_si, &arr(&p["inputs"]["ct3_prime_encaps_rand"]))
        .unwrap();
    assert_eq!(msg3, h(&p["msg3"]), "msg3");
    let ctkc_p = il.on_promote(&msg3, decap(k.si.as_ref().unwrap())).unwrap();
    assert_eq!(ctkc_p.to_vec(), h(&p["ctkc_prime"]), "ctkc'");
    assert_eq!(il.transcript_hash().to_vec(), h(&p["h3_prime"]), "h3'");
    for (side, keys, conf) in [
        ("initiator", il.keys(), il.confirm_key()),
        ("responder", rs.keys(), rs.confirm_key()),
    ] {
        assert_eq!(keys.k_i2r().to_vec(), h(&p["k_i2r"]), "{side}: k_i2r'");
        assert_eq!(keys.k_r2i().to_vec(), h(&p["k_r2i"]), "{side}: k_r2i'");
        assert_eq!(conf.as_bytes().to_vec(), h(&p["k_conf"]), "{side}: k_conf'");
    }
    assert_eq!(il.key_phase(), 1);
    assert_eq!(rs.key_phase(), 1);
    let old = base(&d, p["base"].as_str().unwrap());
    assert_eq!(
        il.previous_keys().unwrap().k_i2r().to_vec(),
        h(&old["k_i2r"])
    );
    assert!(!rs.is_attributed());
    assert_eq!(
        rs.confirm_promotion(&ctkc_p).unwrap(),
        Confirmation::Attributed
    );
    assert!(rs.is_attributed());
    assert_eq!(rs.mode(), Mode::Mutual);
}

#[test]
fn framing_byte_for_byte() {
    let d = doc();
    for f in d["framing"].as_array().unwrap() {
        let c = base(&d, f["base"].as_str().unwrap());
        let msg = h(&c[f["message"].as_str().unwrap()]);
        let max = usize::try_from(f["max_part_len"].as_u64().unwrap()).unwrap();
        let parts = encode_parts(&msg, max).unwrap();
        let want: Vec<Vec<u8>> = f["parts"].as_array().unwrap().iter().map(h).collect();
        assert_eq!(parts, want, "{}", f["name"]);
        let mut r = Reassembler::new();
        let mut out = None;
        for p in &parts {
            out = r.push(p).unwrap();
        }
        assert_eq!(out.unwrap(), msg);
    }
}

fn reassemble(parts: &[Vec<u8>]) -> Result<Vec<u8>, TransitError> {
    let mut r = Reassembler::new();
    for p in parts {
        if let Some(m) = r.push(p)? {
            return Ok(m);
        }
    }
    Err(TransitError::Truncated)
}

#[test]
fn refusals_with_stated_errors() {
    let d = doc();
    let refusals = d["refusals"].as_array().unwrap();
    for r in refusals {
        let name = r["name"].as_str().unwrap();
        let want = r["error"].as_str().unwrap();
        let side = r["side"].as_str().unwrap();
        let got: TransitError = match side {
            "reassemble" => {
                let parts: Vec<Vec<u8>> = r["parts"].as_array().unwrap().iter().map(h).collect();
                reassemble(&parts).unwrap_err()
            },
            _ => {
                let k = Case::from(base(&d, r["base"].as_str().unwrap()));
                match side {
                    "responder_accept" => {
                        let rid = r["responder_key_id_expected"]
                            .as_str()
                            .unwrap_or(&k.rid)
                            .to_owned();
                        k.accept(&h(&r["msg1"]), &rid).unwrap_err()
                    },
                    "initiator_finish" => k.finish(&h(&r["msg2"])).unwrap_err(),
                    "responder_confirm" => {
                        let (_, msg1) = k.start();
                        let (mut rs, _, _) = k.accept(&msg1, &k.rid).unwrap();
                        rs.confirm(&h(&r["ctkc"])).unwrap_err()
                    },
                    "responder_promote" => {
                        let (_, mut rs, _, _) = k.run();
                        let pk =
                            XWingSecretKey::from_seed(arr(&r["promote_static_seed"])).public_key();
                        rs.promote(&pk, &arr(&r["promote_encaps_rand"]))
                            .unwrap_err()
                    },
                    "responder_confirm_promotion" => {
                        let p = &d["promotions"][0];
                        let (_, mut rs, _, _) = k.run();
                        rs.promote(
                            &k.pk_si().unwrap(),
                            &arr(&p["inputs"]["ct3_prime_encaps_rand"]),
                        )
                        .unwrap();
                        rs.confirm_promotion(&h(&r["ctkc"])).unwrap_err()
                    },
                    "initiator_on_promote" => {
                        let (mut il, _, _, _) = k.run();
                        il.on_promote(&h(&r["msg3"]), decap(k.si.as_ref().unwrap()))
                            .unwrap_err()
                    },
                    other => panic!("{name}: unknown side {other}"),
                }
            },
        };
        assert_eq!(got.code(), want, "{name}");
    }
    assert_eq!(refusals.len(), 38);
}

mod properties {
    use super::*;
    use proptest::prelude::*;

    fn handshake(
        seeds: &[[u8; 32]; 3],
        rands: &[[u8; 64]; 3],
        msg1_flip: Option<usize>,
        msg2_flip: Option<usize>,
    ) -> Option<(InitiatorLink, ResponderState)> {
        let link = [0x5a; 16];
        let sr = XWingSecretKey::from_seed(seeds[0]);
        let si = XWingSecretKey::from_seed(seeds[1]);
        let (pr, pi) = (sr.public_key(), si.public_key());
        let (st, mut m1) = Initiator::start(
            &link,
            &pr,
            "responder",
            "initiator",
            Some(&pi),
            &seeds[2],
            &rands[0],
        )
        .unwrap();
        if let Some(bit) = msg1_flip {
            let i = bit / 8 % m1.len();
            m1[i] ^= 1 << (bit % 8);
        }
        let held = pi.clone();
        let (rs, mut m2, _) = Responder::accept(
            &link,
            &pr,
            "responder",
            &m1,
            decap(&sr),
            move |_, _| Some(held),
            &rands[1],
            &rands[2],
        )
        .ok()?;
        if let Some(bit) = msg2_flip {
            let i = bit / 8 % m2.len();
            m2[i] ^= 1 << (bit % 8);
        }
        let il = st.finish(&m2, Some(decap(&si))).ok()?;
        Some((il, rs))
    }

    proptest! {
        #![proptest_config(ProptestConfig { cases: 24, ..ProptestConfig::default() })]

        #[test]
        fn random_mutual_round_trip(
            seeds in any::<[[u8; 32]; 3]>(),
            r in any::<[[u8; 32]; 6]>(),
        ) {
            let rands = [0, 1, 2].map(|i| {
                let mut a = [0u8; 64];
                a[..32].copy_from_slice(&r[2 * i]);
                a[32..].copy_from_slice(&r[2 * i + 1]);
                a
            });
            let (il, mut rs) = handshake(&seeds, &rands, None, None).expect("round trip");
            prop_assert_eq!(il.mode(), Mode::Mutual);
            prop_assert_eq!(il.keys().k_i2r(), rs.keys().k_i2r());
            prop_assert_eq!(il.keys().k_r2i(), rs.keys().k_r2i());
            prop_assert_eq!(rs.confirm(il.ctkc()).unwrap(), Confirmation::Attributed);
        }

        #[test]
        fn a_bit_flip_never_yields_matching_keys(
            seeds in any::<[[u8; 32]; 3]>(),
            bit in any::<usize>(),
            in_msg1 in any::<bool>(),
        ) {
            let rands = [[1u8; 64], [2u8; 64], [3u8; 64]];
            let (f1, f2) = if in_msg1 { (Some(bit), None) } else { (None, Some(bit)) };
            if let Some((il, mut rs)) = handshake(&seeds, &rands, f1, f2) {
                prop_assert_ne!(il.keys().k_i2r(), rs.keys().k_i2r());
                prop_assert!(rs.confirm(il.ctkc()).is_err());
            }
        }
    }
}
